using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text;
using YamlDotNet.RepresentationModel;

namespace Sandbox.Tests;

/// The generated compose file (.state/compose.yml): engine/compose.yml, sandbox.yml, sandbox.local.yml and
/// the host settings merged into the one file docker compose runs with.
public sealed class ComposeFileTests(SandboxFixture f) : SandboxTest(f)
{
    const string Header = """
        # Generated by .sandbox/sandbox — do not edit, change sandbox.yml (or sandbox.local.yml) instead.
        # Merged from engine/compose.yml, sandbox.yml, sandbox.local.yml and this machine's settings.
        # Relative paths are relative to the .sandbox folder.
        """;

    /// Run a cheap docker command so the file is (re)generated, and return its text.
    string Generate()
    {
        var r = Run("status");
        AssertExit(r, 0);
        Assert.True(File.Exists(F.GeneratedFile), $"No generated file.\n{r}");
        return File.ReadAllText(F.GeneratedFile);
    }

    YamlMappingNode GenerateParsed() => Parse(Generate());

    static YamlMappingNode Parse(string text)
    {
        var ys = new YamlStream();
        ys.Load(new StringReader(text));
        return Assert.IsType<YamlMappingNode>(Assert.Single(ys.Documents).RootNode);
    }

    static YamlNode At(YamlNode n, params string[] path)
    {
        foreach (var k in path)
        {
            var m = Assert.IsType<YamlMappingNode>(n);
            Assert.True(m.Children.TryGetValue(new YamlScalarNode(k), out n!), $"missing key '{k}'");
        }
        return n;
    }

    static bool Has(YamlNode n, params string[] path)
    {
        foreach (var k in path)
            if (n is not YamlMappingNode m || !m.Children.TryGetValue(new YamlScalarNode(k), out n!))
                return false;
        return true;
    }

    static string Str(YamlNode n, params string[] path) =>
        Assert.IsType<YamlScalarNode>(At(n, path)).Value!;

    static string[] Seq(YamlNode n, params string[] path) =>
        Assert.IsType<YamlSequenceNode>(At(n, path)).Select(x => ((YamlScalarNode)x).Value!).ToArray();

    static string[] Keys(YamlNode n) =>
        Assert.IsType<YamlMappingNode>(n).Children.Keys.Select(k => ((YamlScalarNode)k).Value!).ToArray();

    record Bind(string Source, string Target, bool ReadOnly);

    /// The bind mounts of the desktop (the generated project mounts; home and the tmpfs placeholder skipped).
    static List<Bind> Binds(YamlNode root) =>
        Assert.IsType<YamlSequenceNode>(At(root, "services", "desktop", "volumes"))
            .OfType<YamlMappingNode>()
            .Where(m => Str(m, "type") == "bind")
            .Select(m =>
            {
                Assert.Equal(["type", "source", "target", "read_only"], Keys(m));
                var ro = Str(m, "read_only");
                Assert.Contains(ro, new[] { "true", "false" });
                return new Bind(Str(m, "source"), Str(m, "target"), ro == "true");
            })
            .ToList();

    /// The desktop's volumes in short form (`src:dst[:mode]`).
    static string[] ShortVolumes(YamlNode root) =>
        Assert.IsType<YamlSequenceNode>(At(root, "services", "desktop", "volumes"))
            .OfType<YamlScalarNode>()
            .Select(v => v.Value!)
            .ToArray();

    /// Every volume's container path, short and long form.
    static string[] Targets(YamlNode root) =>
        Assert.IsType<YamlSequenceNode>(At(root, "services", "desktop", "volumes"))
            .Select(v =>
                v is YamlMappingNode m
                    ? Str(m, "target")
                    : System.Text.RegularExpressions.Regex.Match(((YamlScalarNode)v).Value!, "^(?:[A-Za-z]:)?[^:]*:([^:]+)").Groups[1].Value
            )
            .ToArray();

    Bind Project(bool ro) => new(F.ProjectDir, F.WorkDir, ro);
    Bind SandboxDir => new(F.Dir, F.WorkDir + "/.sandbox", true);
    Bind GitConfig => new(Path.Combine(F.ProjectDir, ".git", "config"), F.WorkDir + "/.git/config", true);
    Bind GitHooks => new(Path.Combine(F.ProjectDir, ".git", "hooks"), F.WorkDir + "/.git/hooks", true);

    [DllImport("libc")]
    static extern uint getuid();

    [DllImport("libc")]
    static extern uint getgid();

    static (uint, uint) ExpectedIds()
    {
        if (OperatingSystem.IsWindows())
            return (1000, 1000);
        var (u, g) = (getuid(), getgid());
        return u == 0 ? (1000, 1000) : (u, g);
    }

    static string Q(string s) => "\"" + s.Replace("\\", "\\\\").Replace("\"", "\\\"") + "\"";

    /// sandbox.yml with extra keys under services.desktop (indented by the caller's YAML).
    void WriteDesktopConf(string desktopYaml) =>
        WriteConf(
            SandboxFixture.DefaultConf.ReplaceLineEndings("\n")
                + "\n"
                + "  # added by the test\n"
                + string.Join("\n", desktopYaml.Split('\n').Select(l => l.Length > 0 ? "    " + l : l))
        );

    // --- the default file -------------------------------------------------------

    [Fact]
    public void Default_file_matches_exactly()
    {
        var (uid, gid) = ExpectedIds();
        string Vol(Bind b) =>
            $"    - {{type: bind, source: {Q(b.Source)}, target: {Q(b.Target)}, read_only: {(b.ReadOnly ? "true" : "false")}}}";
        var expected = string.Join(
            "\n",
            Header.ReplaceLineEndings("\n"),
            "networks:",
            "  sandbox:",
            "    internal: true",
            "  egress: {}",
            "  ui: {}",
            "services:",
            "  proxy:",
            "    build: ./engine/proxy",
            "    command: [\"tinyproxy\", \"-d\", \"-c\", \"/sandbox/engine/proxy/tinyproxy.conf\"]",
            "    networks: [sandbox, egress]",
            "    extra_hosts:",
            "    - \"host.docker.internal:host-gateway\"",
            "    healthcheck:",
            "      test: [\"CMD\", \"nc\", \"-z\", \"127.0.0.1\", \"3128\"]",
            "      interval: 10s",
            "      timeout: 3s",
            "      retries: 3",
            "    read_only: true",
            "    cap_drop: [ALL]",
            "    security_opt: [\"no-new-privileges:true\"]",
            "    restart: unless-stopped",
            "    volumes:",
            "    - .:/sandbox:ro",
            "  gateway:",
            "    build: ./engine/proxy",
            "    command: [\"socat\", \"TCP-LISTEN:3001,fork,reuseaddr\", \"TCP:desktop:3001\"]",
            "    networks: [sandbox, ui]",
            "    depends_on: [proxy]",
            "    read_only: true",
            "    cap_drop: [ALL]",
            "    security_opt: [\"no-new-privileges:true\"]",
            "    restart: unless-stopped",
            "    volumes:",
            "    - .:/sandbox:ro",
            "    ports:",
            "    - \"127.0.0.1::3001\"",
            "  desktop:",
            "    build:",
            "      context: ./engine/desktop",
            "      args:",
            "        INSTALL_CLAUDE: \"true\"",
            "        INSTALL_CLAUDE_CODE: \"false\"",
            "        INSTALL_DOTNET: \"10.0\"",
            "        INSTALL_NODE: \"\"",
            "    hostname: sandbox",
            "    shm_size: 1gb",
            "    environment:",
            "      TITLE: AI Sandbox",
            "      SANDBOX_SUDO: \"true\"",
            "      HTTP_PROXY: http://proxy:3128",
            "      HTTPS_PROXY: http://proxy:3128",
            "      http_proxy: http://proxy:3128",
            "      https_proxy: http://proxy:3128",
            "      NO_PROXY: localhost,127.0.0.1,::1",
            "      no_proxy: localhost,127.0.0.1,::1",
            $"      PUID: \"{uid}\"",
            $"      PGID: \"{gid}\"",
            "      TZ: \"Europe/Vienna\"",
            $"      SANDBOX_WORKDIR: \"{F.WorkDir}\"",
            "    volumes:",
            "    - home:/config",
            "    - type: tmpfs",
            "      target: /shares",
            Vol(Project(false)),
            Vol(SandboxDir),
            Vol(GitConfig),
            Vol(GitHooks),
            "    networks: [sandbox]",
            "    mem_limit: 8g",
            "    pids_limit: 4096",
            "    depends_on: [proxy]",
            "    restart: unless-stopped",
            "    healthcheck:",
            "      test: [\"CMD-SHELL\", \"curl -skf -o /dev/null https://localhost:3001/ && pgrep -f plasmashell >/dev/null\"]",
            "      interval: 5s",
            "      timeout: 5s",
            "      retries: 3",
            "      start_period: 180s",
            "    labels:",
            $"      sandbox.id: \"{SandboxFixture.Id}\"",
            "volumes:",
            "  home: null",
            ""
        );
        var text = Generate();
        Assert.Equal(expected, text);
        Assert.DoesNotContain("\r", text);
        Assert.DoesNotContain("\n...", text);
        Assert.False(File.ReadAllBytes(F.GeneratedFile).AsSpan().StartsWith(Encoding.UTF8.Preamble), "BOM");
    }

    [Fact]
    public void Default_file_is_self_contained()
    {
        var text = Generate();
        var root = Parse(text);
        Assert.Equal(["networks", "services", "volumes"], Keys(root));
        Assert.Equal(["proxy", "gateway", "desktop"], Keys(At(root, "services")));
        Assert.DoesNotContain("<<", text);
        Assert.DoesNotContain("*hardened", text);
        Assert.DoesNotContain("x-sandbox", text);
        Assert.DoesNotContain("x-hardened", text);

        Assert.Equal(["127.0.0.1::3001"], Seq(root, "services", "gateway", "ports"));
        Assert.Equal(SandboxFixture.Id, Str(root, "services", "desktop", "labels", "sandbox.id"));
        Assert.Equal(F.WorkDir, Str(root, "services", "desktop", "environment", "SANDBOX_WORKDIR"));
        Assert.Equal("Europe/Vienna", Str(root, "services", "desktop", "environment", "TZ"));
        Assert.Equal([Project(false), SandboxDir, GitConfig, GitHooks], Binds(root));
    }

    /// Every service from engine/compose.yml is there; the x-hardened settings are applied to proxy and gateway.
    [Fact]
    public void Engine_services_and_hardening_are_included()
    {
        var root = GenerateParsed();
        var engine = Parse(File.ReadAllText(Path.Combine(F.Dir, "engine", "compose.yml")));
        Assert.Equal(Keys(At(engine, "services")), Keys(At(root, "services")));
        foreach (var s in new[] { "proxy", "gateway" })
        {
            Assert.Equal("true", Str(root, "services", s, "read_only"));
            Assert.Equal(["ALL"], Seq(root, "services", s, "cap_drop"));
            Assert.Equal(["no-new-privileges:true"], Seq(root, "services", s, "security_opt"));
            Assert.Equal([".:/sandbox:ro"], Seq(root, "services", s, "volumes"));
        }
        Assert.False(Has(root, "services", "desktop", "read_only"));
        Assert.Contains("TCP-LISTEN:3001,fork,reuseaddr", Seq(root, "services", "gateway", "command"));
    }

    // --- x-sandbox settings -----------------------------------------------------

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void Fixed_ui_port(bool viaLocal)
    {
        if (viaLocal)
        {
            WriteConf(File.ReadAllText(F.ConfFile).Replace("# ui_port: 3001", "ui_port: 4000"));
            WriteLocalConf("x-sandbox:\n  ui_port: 3002\n");
        }
        else
            WriteConf(File.ReadAllText(F.ConfFile).Replace("# ui_port: 3001", "ui_port: 3002"));
        Assert.Equal(["127.0.0.1:3002:3001"], Seq(GenerateParsed(), "services", "gateway", "ports"));
    }

    [Fact]
    public void Read_only_workspace_has_no_git_mounts()
    {
        WriteConf(File.ReadAllText(F.ConfFile).Replace("workspace_mode: rw", "workspace_mode: ro"));
        Assert.Equal([Project(true), SandboxDir], Binds(GenerateParsed()));
    }

    [Fact]
    public void Local_override_wins_over_sandbox_yml()
    {
        WriteLocalConf("x-sandbox:\n  workspace_mode: ro\n");
        Assert.Equal([Project(true), SandboxDir], Binds(GenerateParsed()));
    }

    [Fact]
    public void Protect_git_off()
    {
        WriteConf(File.ReadAllText(F.ConfFile).Replace("protect_git: true", "protect_git: false"));
        Assert.Equal([Project(false), SandboxDir], Binds(GenerateParsed()));
    }

    [Fact]
    public void Only_existing_git_paths_are_protected()
    {
        Directory.Delete(Path.Combine(F.ProjectDir, ".git", "hooks"));
        Assert.Equal([Project(false), SandboxDir, GitConfig], Binds(GenerateParsed()));

        Directory.Delete(Path.Combine(F.ProjectDir, ".git"), recursive: true);
        Assert.Equal([Project(false), SandboxDir], Binds(GenerateParsed()));
    }

    [Fact]
    public void Project_name_does_not_change_the_mount_path()
    {
        WriteConf(File.ReadAllText(F.ConfFile).Replace("# project_name: myproject", "project_name: other"));
        Assert.Equal(F.WorkDir, Str(GenerateParsed(), "services", "desktop", "environment", "SANDBOX_WORKDIR"));
    }

    [Fact]
    public void A_new_id_is_derived_from_the_project_path_and_kept()
    {
        File.Delete(F.IdFile);
        var id = Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes(F.ProjectDir)))[..8];
        var root = GenerateParsed();
        Assert.Equal(id + "\n", File.ReadAllText(F.IdFile));
        Assert.Equal(id, Str(root, "services", "desktop", "labels", "sandbox.id"));
        Assert.Equal(
            $"/work/{SandboxFixture.ProjectName}-{id}",
            Str(root, "services", "desktop", "environment", "SANDBOX_WORKDIR")
        );

        // a stored id is used as-is, even if it doesn't match the path (the project was moved)
        File.WriteAllText(F.IdFile, "cafebabe\n");
        Assert.Equal("cafebabe", Str(GenerateParsed(), "services", "desktop", "labels", "sandbox.id"));
    }

    [Fact]
    public void File_is_regenerated_on_every_docker_command()
    {
        File.WriteAllText(F.GeneratedFile, "stale");
        Assert.StartsWith(Header.ReplaceLineEndings("\n") + "\n", Generate());
        foreach (var cmd in new[] { "stop", "reload", "logs" })
        {
            File.WriteAllText(F.GeneratedFile, "stale");
            AssertExit(Run(cmd), 0);
            Assert.StartsWith(Header.ReplaceLineEndings("\n") + "\n", File.ReadAllText(F.GeneratedFile));
        }
    }

    [Fact]
    public void The_old_override_file_is_removed()
    {
        var old = Path.Combine(F.StateDir, "compose.generated.yml");
        File.WriteAllText(old, "services: {}\n");
        Generate();
        Assert.False(File.Exists(old));
    }

    // --- merge rules ------------------------------------------------------------

    [Fact]
    public void Scalars_from_sandbox_yml_win_and_new_keys_are_added()
    {
        WriteDesktopConf("mem_limit: 4g\ncpus: 2\n");
        var root = GenerateParsed();
        Assert.Equal("4g", Str(root, "services", "desktop", "mem_limit"));
        Assert.Equal("2", Str(root, "services", "desktop", "cpus"));
        Assert.Equal("4096", Str(root, "services", "desktop", "pids_limit"));
    }

    [Fact]
    public void Build_args_keep_the_engine_build_context()
    {
        var root = GenerateParsed();
        Assert.Equal("./engine/desktop", Str(root, "services", "desktop", "build", "context"));
        Assert.Equal("10.0", Str(root, "services", "desktop", "build", "args", "INSTALL_DOTNET"));
    }

    [Fact]
    public void Environment_in_list_form_is_merged_by_key()
    {
        WriteLocalConf("services:\n  desktop:\n    environment:\n      - TITLE=Mine\n      - EXTRA=a=b\n      - PASSTHROUGH\n");
        var root = GenerateParsed();
        var env = At(root, "services", "desktop", "environment");
        Assert.Equal("Mine", Str(env, "TITLE"));
        Assert.Equal("a=b", Str(env, "EXTRA"));
        Assert.Equal("null", Str(env, "PASSTHROUGH"));
        Assert.Equal("http://proxy:3128", Str(env, "HTTP_PROXY"));
    }

    [Fact]
    public void Build_args_in_list_form_are_merged_by_key()
    {
        WriteLocalConf("services:\n  desktop:\n    build:\n      args:\n        - INSTALL_NODE=24\n");
        var args = At(GenerateParsed(), "services", "desktop", "build", "args");
        Assert.Equal("24", Str(args, "INSTALL_NODE"));
        Assert.Equal("true", Str(args, "INSTALL_CLAUDE"));
    }

    [Fact]
    public void Volumes_are_merged_by_target()
    {
        WriteLocalConf(
            "services:\n  desktop:\n    volumes:\n      - C:/data:/shares:ro\n      - ../docs:/shares/docs:ro\n      - other-home:/config\n"
        );
        var root = GenerateParsed();
        var targets = Targets(root);
        Assert.Equal(targets.Distinct(), targets);
        Assert.Equal(["other-home:/config", "C:/data:/shares:ro", "../docs:/shares/docs:ro"], ShortVolumes(root));
        Assert.DoesNotContain("/shares", Binds(root).Select(b => b.Target));
    }

    [Fact]
    public void Command_and_healthcheck_test_are_replaced()
    {
        WriteLocalConf(
            "services:\n  proxy:\n    command: [\"tinyproxy\", \"-d\"]\n    healthcheck:\n      test: [\"CMD\", \"true\"]\n      interval: 30s\n"
        );
        var root = GenerateParsed();
        Assert.Equal(["tinyproxy", "-d"], Seq(root, "services", "proxy", "command"));
        Assert.Equal(["CMD", "true"], Seq(root, "services", "proxy", "healthcheck", "test"));
        Assert.Equal("30s", Str(root, "services", "proxy", "healthcheck", "interval"));
        Assert.Equal("3", Str(root, "services", "proxy", "healthcheck", "retries"));
    }

    [Fact]
    public void Other_sequences_are_combined_without_duplicates()
    {
        WriteLocalConf(
            "services:\n  desktop:\n    devices: [\"/dev/dri:/dev/dri\"]\n  proxy:\n    security_opt: [\"no-new-privileges:true\", \"seccomp=unconfined\"]\n"
        );
        var root = GenerateParsed();
        Assert.Equal(["/dev/dri:/dev/dri"], Seq(root, "services", "desktop", "devices"));
        Assert.Equal(
            ["no-new-privileges:true", "seccomp=unconfined"],
            Seq(root, "services", "proxy", "security_opt")
        );
    }

    [Fact]
    public void Networks_in_mapping_form_are_merged_with_the_list()
    {
        WriteLocalConf("services:\n  desktop:\n    networks:\n      sandbox:\n        aliases: [box]\n");
        var root = GenerateParsed();
        Assert.Equal(["box"], Seq(root, "services", "desktop", "networks", "sandbox", "aliases"));
    }

    [Fact]
    public void Reset_removes_and_override_replaces()
    {
        WriteLocalConf(
            "services:\n  desktop:\n    shm_size: !reset null\n  proxy:\n    extra_hosts: !override [\"a.local:1.2.3.4\"]\n"
        );
        var text = Generate();
        Assert.DoesNotContain("!reset", text);
        Assert.DoesNotContain("!override", text);
        var root = Parse(text);
        Assert.False(Has(root, "services", "desktop", "shm_size"));
        Assert.Equal(["a.local:1.2.3.4"], Seq(root, "services", "proxy", "extra_hosts"));
    }

    [Fact]
    public void Sandbox_yml_overrides_host_defaults()
    {
        WriteLocalConf("services:\n  desktop:\n    environment:\n      TZ: Asia/Tokyo\n      PUID: \"1234\"\n");
        var env = At(GenerateParsed(), "services", "desktop", "environment");
        Assert.Equal("Asia/Tokyo", Str(env, "TZ"));
        Assert.Equal("1234", Str(env, "PUID"));
    }

    /// The UI port, the sandbox.id label, the workdir and the project mounts always come from the app.
    [Fact]
    public void Host_settings_can_not_be_overridden()
    {
        WriteLocalConf(
            $"""
            services:
              gateway:
                ports: ["0.0.0.0:80:3001"]
              desktop:
                labels:
                  sandbox.id: other
                environment:
                  SANDBOX_WORKDIR: /elsewhere
                volumes:
                  - /:{F.WorkDir}/.sandbox:rw
            """
        );
        var root = GenerateParsed();
        Assert.Equal(["127.0.0.1::3001"], Seq(root, "services", "gateway", "ports"));
        Assert.Equal(SandboxFixture.Id, Str(root, "services", "desktop", "labels", "sandbox.id"));
        Assert.Equal(F.WorkDir, Str(root, "services", "desktop", "environment", "SANDBOX_WORKDIR"));
        // replaced in place; the order doesn't matter, Docker mounts parents before children
        Assert.Equivalent(new[] { Project(false), SandboxDir, GitConfig, GitHooks }, Binds(root), strict: true);
        Assert.DoesNotContain($"/:{F.WorkDir}/.sandbox:rw", Generate());
    }

    [Theory]
    [InlineData("include:\n  - other.yml\n", "sandbox.local.yml: 'include' is not supported.")]
    [InlineData("services:\n  desktop:\n    extends: base\n", "sandbox.local.yml: services.desktop.extends is not supported.")]
    [InlineData("services: [desktop]\n", "sandbox.local.yml: services must be a mapping.")]
    public void Unsupported_compose_features_are_reported(string yaml, string message)
    {
        WriteLocalConf(yaml);
        var r = Run("status");
        AssertExit(r, 1);
        AssertOutput(r, message);
    }
}
